const d = new Date(Date.now() - 24 * 60 * 60 * 1000);
const pad = n => String(n).padStart(2, '0');
const ymd = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
return [{
  json: {
    since: `${ymd} 00:00:00`,
    until: `${ymd} 23:59:59`,
    dateLabel: ymd
  }
}];

const raw = $input.first().json.data || [];

const keep = /error|fail(?:ed|ure)?|warn|critical|denied|timeout|panic|oom|degraded|corrupt|unreachable|refused|expired|exceeded|bounced|blocked|deferred|rejected|unauthenticated|reset by peer|retry|retries|nic link is (down|up)|no.?carrier|netdev watchdog|bonding:.*(down|fail)|link is down|stp topology change|rx_error|tx_error/i;

// Bridge-port state changes on a REAL physical/bond NIC are worth flagging (uplink flapping).
// Changes on virtual VM interfaces (tap/veth/fwln/fwpr/fwbr) are normal VM start/stop noise, so they're excluded.
const physicalIfaceBridgeChange = /vmbr\d+: port \d+\((?!tap|veth|fwln|fwpr|fwbr)[a-z0-9.]+\) entered (disabled|blocking) state/i;

let lines = raw
  .map(l => l.t)
  .filter(t => keep.test(t) || physicalIfaceBridgeChange.test(t));

const counts = new Map();
for (const line of lines) {
  const key = line.replace(/^\S+\s+\d+\s+[\d:]+\s+\S+\s+/, '').trim();
  counts.set(key, (counts.get(key) || 0) + 1);
}

const deduped = [...counts.entries()].map(([msg, n]) => n > 1 ? `[x${n}] ${msg}` : msg);

return [{
  json: {
    text: deduped.join('\n'),
    originalLineCount: raw.length,
    filteredLineCount: lines.length,
    dedupedLineCount: deduped.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

const data = $input.first().json;
const lines = data.text.split('\n').filter(Boolean);
const CHUNK_SIZE = 1200; // lines per chunk, keeps each AI call well inside context limits
const chunks = [];
for (let i = 0; i < lines.length; i += CHUNK_SIZE) {
  chunks.push(lines.slice(i, i + CHUNK_SIZE).join('\n'));
}
if (chunks.length === 0) chunks.push('(no notable lines after filtering)');

return chunks.map((text, idx) => ({
  json: {
    text,
    chunkIndex: idx + 1,
    totalChunks: chunks.length,
    dateLabel: data.dateLabel
  }
}));

const content = $input.item.json.text ?? '';
const chunkInfo = $('Chunk Log For Analysis').item.json;
return [{
  json: {
    chunkIndex: chunkInfo.chunkIndex,
    extracted: content
  }
}];

const items = $input.first().json.data || [];
const list = items.map(i => i.extracted).filter(Boolean);
const meaningful = list.filter(x => x.trim().toUpperCase() !== 'NONE');
const combined = meaningful.length ? meaningful.join('\n') : 'NONE';

return [{
  json: {
    combinedIssues: combined,
    totalChunks: list.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

