const raw = ($input.item.json.text ?? '').trim();
const status = /^STATUS:\s*ISSUES/i.test(raw) ? 'ISSUES' : 'OK';
return [{
  json: {
    report: raw,
    status,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];
